list_shipping_rules.code:
import (
	"fmt"
)

resp, err := client.ShippingRules().ListShippingRules(ctx, map[string]any{
	"zone_id":       5,
	"method":        "flat_rate",
	"handling_cost": "without_handling",
	"sort":          "name",
	"order":         "asc",
}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["shipping_rules"].([]any) {
	rule := row.(map[string]any)
	fmt.Println(rule["id"], rule["name"], rule["shipping_class"], rule["shipping_rate"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])

